import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·5","description":"易小帖 - 卷二·5","frontmatter":{"title":"卷二·5","description":"易小帖 - 卷二·5"},"headers":[],"relativePath":"zh/classics/yixiaotie/045.md","filePath":"zh/classics/yixiaotie/045.md"}'),o={name:"zh/classics/yixiaotie/045.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·5",tabindex:"-1"},[r("卷二·5 "),e("a",{class:"header-anchor",href:"#卷二·5","aria-label":"Permalink to “卷二·5”"},"​")],-1),e("p",null,"豐之初爻「雖旬無咎」，旬者十日之名，鄭康成所謂十日者朝聘之禮是也。自荀慈明本作均字，而王輔嗣遂註旬為均，致《程傳》、《本義》俱以均字為旬字釋間。嘗疑之，及考《周禮》「均人」註，「凡均力政，以歲上下，豐年則公旬用三日焉，中年則公旬用二日焉，無年則公旬用一日焉」康成註雲：「旬，均也。」引《易》「坤為均，今書亦有作旬者」為証，此即荀王釋均之所始。第細繹禮文，此是康成誤註者。按：公旬三日，此與《王制》用民之力不過歲三日同，其曰公旬者，非謂均人公役必當限以十日也。歲以日為始，日以旬為終，但言旬而日之成數已該，所謂公旬亦祗曰公役之日雲耳。康成意以為三日兩日不當稱旬，故遂註為均，此孔仲達疏鄭意所謂三日非十日者。然以均人、均力而立為均政，亦何難直作均字，且本文前後凡為均字者不止十餘，獨此一字忽以異形參其間，世無是理。若《內則》「旬而見」文亦註作均，此即康成註公旬之成見而一誤致再誤者。按《內則》：「由命士以上及大夫之子，旬而見。冢子未食而見，適子、庶子已食而見。」其所雲「旬而見」者，正雲越十日而始得見也，曰「未食」、「已食」者，於十日之際，見時或已食或未食也。乃註旬為均，則其義難解，於是增其說雲：有時適妾同時生子，均而見者，以生之先後見之。既見乃食。則於本文既周章不明，而且增同時生子之說，傅會增飾，大無理矣。若其引均旬字義証左絶罕，既引易《說卦傳》坤為均，有今本作旬字為証，則有無今本原不足憑，縱有之，亦字形之誤，非本義也。乃既取作証，而其註《內則》則又雲旬字是均聲之誤，則仍屬誤字，並非字義。且幾見均旬為同聲者，即此兩證皆周章之特甚者，而王氏承誤註旬為均，是王氏作註本欲攻鄭氏之短，而此獨拾其棄唾而不自知何也。況康成註易，則又仍作十日也。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
